db
    .select({
      unpaid: sql<number>`count(*) filter (where ${invoices.status} in ('envoyee','en_retard'))::int`,
      unpaidCents: sql<number>`coalesce(sum(${invoices.amountCents}) filter (where ${invoices.status} in ('envoyee','en_retard')), 0)::int`,
    })
    .from
